### 3.2 `Gateway.Security` – JWT AuthN/Z

**Project file (`Gateway.Security.csproj`)**

```xml
<Project Sdk="Microsoft.NET.Sdk">

  <PropertyGroup>
    <TargetFramework>net8.0</TargetFramework>
    <Nullable>enable</Nullable>
    <ImplicitUsings>enable</ImplicitUsings>
  </PropertyGroup>

  <ItemGroup>
    <PackageReference Include="Microsoft.AspNetCore.Authentication.JwtBearer" Version="8.0.0" />
  </ItemGroup>

</Project>
```

**`JwtOptions.cs`**

```csharp
namespace Gateway.Security;

/// <summary>
/// Strongly‑typed JWT configuration bound from "Jwt" section.
/// </summary>
public sealed class JwtOptions
{
    public string Authority { get; init; } = string.Empty;
    public string Audience { get; init; } = string.Empty;
    public bool RequireHttpsMetadata { get; init; } = true;
    public string[] ValidIssuers { get; init; } = Array.Empty<string>();
    public string[] ValidAudiences { get; init; } = Array.Empty<string>();
}
```

**`SecurityExtensions.cs`**

```csharp
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.IdentityModel.Tokens;

namespace Gateway.Security;

public static class SecurityExtensions
{
    /// <summary>
    /// Registers JWT bearer authentication and a policy that checks required scopes.
    /// </summary>
    public static IServiceCollection AddGatewaySecurity(this IServiceCollection services, IConfiguration config)
    {
        // Bind strongly typed options
        var jwtOptions = config.GetSection("Jwt").Get<JwtOptions>()
            ?? throw new InvalidOperationException("Jwt configuration missing.");

        services.Configure<JwtOptions>(config.GetSection("Jwt"));

        // ---------- Authentication ----------
        services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
                .AddJwtBearer(options =>
                {
                    options.Authority = jwtOptions.Authority;
                    options.Audience = jwtOptions.Audience;
                    options.RequireHttpsMetadata = jwtOptions.RequireHttpsMetadata;

                    // Use the default token validation parameters + explicit whitelists
                    options.TokenValidationParameters = new TokenValidationParameters
                    {
                        ValidateIssuer = true,
                        ValidIssuers = jwtOptions.ValidIssuers,
                        ValidateAudience = true,
                        ValidAudiences = jwtOptions.ValidAudiences,
                        ValidateLifetime = true,
                        ValidateIssuerSigningKey = true,
                        // In production you will usually use a signing key resolver (e.g., JWKS)
                    };
                });

        // ---------- Authorization ----------
        services.AddAuthorization(options =>
        {
            // Generic policy that checks for a "scope" claim.
            options.AddPolicy("ScopeRequired", policy =>
            {
                policy.RequireAuthenticatedUser();
                policy.RequireAssertion(context =>
                {
                    // "scope" claim may contain space‑separated list
                    var scopeClaim = context.User.FindFirst("scope")?.Value;
                    if (string.IsNullOrEmpty(scopeClaim))
                        return false;

                    var requiredScopes = context.Requirements
                                               .OfType<ScopeRequirement>()
                                               .Select(r => r.Scope);

                    return requiredScopes.All(rs => scopeClaim.Split(' ', StringSplitOptions.RemoveEmptyEntries)
                                                             .Contains(rs));
                });
            });
        });

        // Register a custom requirement handler for compile‑time safety
        services.AddSingleton<IAuthorizationHandler, ScopeRequirementHandler>();

        return services;
    }

    /// <summary>
    /// Helper to require a specific scope on an endpoint.
    /// </summary>
    public static RouteHandlerBuilder RequireScope(this RouteHandlerBuilder builder, string scope)
    {
        return builder.RequireAuthorization(new ScopeRequirement(scope));
    }

    // ---------- Helper types ----------
    private sealed record ScopeRequirement(string Scope) : IAuthorizationRequirement;

    private sealed class ScopeRequirementHandler : AuthorizationHandler<ScopeRequirement>
    {
        protected override Task HandleRequirementAsync(AuthorizationHandlerContext context,
                                                       ScopeRequirement requirement)
        {
            var scopeClaim = context.User.FindFirst("scope")?.Value;
            if (scopeClaim != null &&
                scopeClaim.Split(' ', StringSplitOptions.RemoveEmptyEntries).Contains(requirement.Scope))
            {
                context.Succeed(requirement);
            }

            return Task.CompletedTask;
        }
    }
}
```

**Usage in the host (later)**
```csharp
app.MapReverseProxy()
   .RequireAuthorization("ScopeRequired"); // optional per‑route scope enforcement
```

