### 3.3 `Gateway.Tracing` – OpenTelemetry + Correlation ID

**Project file (`Gateway.Tracing.csproj`)**

```xml
<Project Sdk="Microsoft.NET.Sdk">

  <PropertyGroup>
    <TargetFramework>net8.0</TargetFramework>
    <Nullable>enable</Nullable>
    <ImplicitUsings>enable</ImplicitUsings>
  </PropertyGroup>

  <ItemGroup>
    <PackageReference Include="OpenTelemetry.Extensions.Hosting" Version="1.6.0" />
    <PackageReference Include="OpenTelemetry.Instrumentation.AspNetCore" Version="1.6.0" />
    <PackageReference Include="OpenTelemetry.Instrumentation.Http" Version="1.6.0" />
    <PackageReference Include="OpenTelemetry.Exporter.Jaeger" Version="1.6.0" />
  </ItemGroup>

</Project>
```

**`TracingOptions.cs`**

```csharp
namespace Gateway.Tracing;

public sealed class TracingOptions
{
    public string Exporter { get; init; } = "Jaeger";
    public string ServiceName { get; init; } = "gateway-api";

    // Jaeger specific
    public string JaegerAgentHost { get; init; } = "localhost";
    public int JaegerAgentPort { get; init; } = 6831;
}
```

**`TracingExtensions.cs`**

```csharp
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using OpenTelemetry;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;

namespace Gateway.Tracing;

public static class TracingExtensions
{
    /// <summary>
    /// Configures OpenTelemetry (Jaeger exporter by default) and registers a middleware that
    /// injects a correlation‑id (X‑Correlation‑Id) into outbound HTTP calls.
    /// </summary>
    public static IServiceCollection AddGatewayTracing(this IServiceCollection services, IConfiguration config)
    {
        var opts = config.GetSection("OpenTelemetry").Get<TracingOptions>()
            ?? throw new InvalidOperationException("OpenTelemetry config missing.");

        services.Configure<TracingOptions>(config.GetSection("OpenTelemetry"));

        services.AddOpenTelemetryTracing(builder =>
        {
            builder
                .SetResourceBuilder(ResourceBuilder.CreateDefault()
                    .AddService(opts.ServiceName))
                .AddAspNetCoreInstrumentation(options =>
                {
                    // Enrich with the correlation id so downstream services can see it
                    options.Enrich = (activity, eventName, obj) =>
                    {
                        if (eventName == "OnStartActivity")
                        {
                            if (obj is HttpRequest httpRequest &&
                                httpRequest.Headers.TryGetValue("X-Correlation-Id", out var corr))
                            {
                                activity.SetTag("http.request.header.correlation_id", corr.ToString());
                            }
                        }
                    };
                })
                .AddHttpClientInstrumentation()
                .AddProcessor(new SimpleExportProcessor<Activity>(GetExporter(opts)));
        });

        // Middleware that guarantees a correlation id exists and propagates it.
        services.AddSingleton<CorrelationIdMiddleware>();

        return services;
    }

